<template>
<view class="wishlist-page">
 <view class="section-top"><view><text class="page-title">{{user.role==='admin'?'心愿审批':'心愿清单'}}</text><text class="muted">没有找到想用的器材？提出你的想法，看看还有多少人也想要。</text></view><button role="button" class="btn secondary" :disabled="loading||!!voting||submitting" @click="load(data.page)">刷新人数</button></view>
 <view v-if="user.role==='student'" class="chips wish-tabs" role="group" aria-label="心愿清单栏目"><button role="button" :class="['chip',{selected:tab==='all'}]" @click="tab='all'">大家都在申请</button><button role="button" :class="['chip',{selected:tab==='create'}]" @click="openCreate">我想申请</button></view>
 <view v-if="unavailable" class="wish-unavailable" role="status"><text class="block-title">心愿清单服务暂未开放</text><text>暂时不能查看、提交或支持心愿。服务开放后，大家提出的器材会在这里共享展示。</text><button role="button" class="text-btn" :disabled="loading" @click="load(1)">重新检查 ›</button></view>
 <text v-if="ready" class="small wish-sync">支持人数由所有账号共享统计，每个账号只计一次，可取消支持；页面每15秒更新。{{syncError}}</text><view v-if="error" class="error" role="alert">{{error}}</view><view v-if="notice" :class="['success','wish-toast',{'wish-toast-fading':noticeFading}]" role="status">{{notice}}</view>
 <view v-if="tab==='all'" class="chips"><button v-for="option in stageFilters" :key="option.value" role="button" :class="['chip',{selected:(user.role==='admin'?status:stage)===option.value}]" @click="chooseStage(option.value)">{{option.label}}</button></view>
 <template v-if="tab==='all'">
  <view class="wish-filter"><view class="search-box"><input v-model="keyword" class="field" placeholder="搜索想要的器材或型号" maxlength="100" @confirm="load(1)"/><button role="button" class="btn" :disabled="loading" @click="load(1)">搜索</button></view><view class="chips"><button role="button" :class="['chip',{selected:!category}]" @click="category='';load(1)">全部</button><button v-for="c in WISH_CATEGORIES" :key="c" role="button" :class="['chip',{selected:category===c}]" @click="category=c;load(1)">{{c}}</button></view></view>
  <text v-if="loading" class="loading">正在查看大家的心愿…</text>
  <view class="wish-grid"><view v-for="row in data.items" :key="row.id" class="wish-card" :data-wish-id="row.id"><view class="wish-art"><image v-if="row.image" :src="row.image" mode="aspectFit"/><template v-else><image src="/static/icons/equipment.png" mode="aspectFit"/><text>{{row.category}}</text></template></view><view class="wish-body"><view class="card-title-row"><text class="card-title">{{row.name}}</text><text v-if="user.role==='admin'||wishStageLabel(row)" class="status">{{user.role==='admin'&&row.procurementStage!=='stocked'?statusNames[row.status]:wishStageLabel(row)}}</text></view><text v-if="row.model" class="muted">{{row.model}}</text><view class="wish-detail-section"><text class="wish-detail-label">用途</text><text class="wish-description">{{row.description}}</text></view><view v-if="row.function" class="wish-detail-section"><text class="wish-detail-label">功能</text><text class="wish-description">{{row.function}}</text></view><view v-if="references(row).length" class="wish-reference-list"><button v-for="(link,index) in references(row)" :key="index" role="button" class="text-btn wish-reference" @click="openReference(link)">商品 / 资料 {{index+1}} ↗<text>{{link}}</text></button></view><text v-if="row.status==='approved'&&row.procurementStage!=='stocked'" class="small">已列入计划，采购到货后由管理员手动入库；当前不增加可借库存。</text><button v-if="row.procurementStage==='stocked'&&row.stockedEquipmentId" role="button" class="text-btn" @click="$emit('borrow',row.stockedEquipmentId)">查看已上架器材 →</button><text v-if="row.reason" class="wish-description">审批说明：{{row.reason}}</text><view class="wish-card-footer"><text>{{row.supportCount}} 人也想要</text><button role="button" :class="['btn',row.supportedByMe?'secondary':'']" :disabled="!isGuest&&(!interactionReady||voting===row.id||(row.status==='rejected'&&!row.supportedByMe))" :aria-label="row.supportedByMe?'已支持，点击取消支持':'我也想要'" :aria-disabled="!isGuest&&(!interactionReady||voting===row.id||(row.status==='rejected'&&!row.supportedByMe))" @click="support(row)">{{voting===row.id?'正在确认…':row.supportedByMe?'已支持':'我也想要'}}</button></view><view v-if="user.role==='admin'&&row.allowedActions?.includes('approve')" class="wish-review"><textarea v-model="reasons[row.id]" class="field textarea" placeholder="不通过时请填写原因（必填）" maxlength="500"/><view class="button-row"><button role="button" class="btn" :disabled="!canWrite" @click="review(row,'approve')">批准采购</button><button role="button" class="btn secondary" :disabled="!canWrite" @click="review(row,'reject')">不通过</button></view></view><template v-if="user.role==='admin'&&row.allowedActions?.includes('stocked')"><button role="button" class="text-btn" @click="$emit('inventory')">采购到货后去器材维护手动入库 →</button><button role="button" class="btn secondary wish-stock-button" :disabled="!canWrite" @click="beginStocked(row)">确认已采购并上架</button><view v-if="stockingId===row.id" class="wish-stock-form"><text class="small">请先完成实际入库，再关联对应器材。此次确认只登记采购状态，不增加库存。</text><ChoiceField v-model="stockedEquipmentId" :options="[{value:'',label:'选择已上架且有受管库存的器材'},...stockOptions]"/><checkbox-group @change="stockConfirmed=$event.detail.value.includes('confirmed')"><label class="check-row"><checkbox value="confirmed" :checked="stockConfirmed"/><text>已核实采购到货并完成手动入库</text></label></checkbox-group><view class="button-row"><button role="button" class="btn" :disabled="!canWrite||!stockConfirmed||!stockedEquipmentId" @click="markStocked(row)">记录采购上架</button><button role="button" class="text-btn" :disabled="!!voting" @click="stockingId=''">取消</button></view></view></template></view></view></view>
  <view v-if="!loading&&ready&&!data.items.length" class="panel empty"><text>{{category||keyword?'没有找到相应的心愿':'还没有人提出心愿'}}</text><button v-if="user.role==='student'" role="button" class="text-btn" @click="openCreate">我来提出一个 ›</button></view>
  <ServerPager v-if="ready" :total="data.total" :page="data.page" :page-size="9" :disabled="loading||!!voting" @change="load"/>
  <view v-if="user.role==='student'&&(unavailable||(ready&&!data.total&&!category&&!keyword&&!status))" class="wish-example">
   <view class="section-top"><view><text class="block-title">填写示例</text><text class="muted">以下仅用于说明如何申请，不是真实申请，不计入条目总数和支持人数。</text></view></view>
   <view class="wish-grid"><view class="wish-card wish-example-card"><view class="wish-art"><image src="/static/icons/equipment.png" mode="aspectFit"/><text>{{wishExample.category}}</text><text class="wish-example-badge">示例</text></view><view class="wish-body"><text class="card-title">{{wishExample.name}}</text><text class="muted">型号：暂不指定</text><text class="wish-description">{{wishExample.description}}</text><view class="wish-card-footer"><text>填写模板，不参与支持统计</text><button role="button" class="btn secondary" @click="useExample">按此模板申请</button></view><button role="button" class="text-btn wish-example-fill" @click="useExample">使用此示例填写 →</button></view></view></view>
  </view>
 </template>
 <view v-else class="panel wish-form"><text class="block-title">我想申请</text><text class="muted">先描述想用的器材和用途。支持人数作为采购参考，提交心愿不代表已获批采购。</text><view class="wish-form-example"><text class="small">不知道如何描述？可以先填入示例，再修改成自己的需求。</text><button role="button" class="text-btn" :disabled="submitting" :aria-disabled="submitting" @click="useExample">使用示例填写 →</button></view><view class="field-group"><text>器材名称 *</text><input v-model="form.name" class="field" placeholder="例如：六轴机器人" maxlength="160"/></view><view class="time-fields"><view class="field-group"><text>型号（选填）</text><input v-model="form.model" class="field" placeholder="填写已了解的型号" maxlength="100"/></view><view class="field-group"><text>器材分类 *</text><ChoiceField v-model="form.category" :options="WISH_CATEGORIES.map(c=>({value:c,label:c}))"/></view></view><view class="field-group"><text>功能（选填）</text><textarea v-model="form.function" class="field textarea" placeholder="例如：图像采集、处理与显示，希望配套摄像头和显示屏" maxlength="2000"/><text class="small field-help">描述器材需要具备的功能或配套要求。</text></view><view class="field-group"><text>用途 *</text><textarea v-model="form.description" class="field textarea" placeholder="例如：学科竞赛、课程设计、课题研究、自主探索；请说明具体任务" maxlength="2000"/></view><view class="field-group wish-links-field"><view class="section-heading"><text>商品或资料链接（选填）</text><button role="button" class="text-btn" :disabled="submitting" @click="form.urls.push('')">＋ 添加链接</button></view><view v-for="(_,index) in form.urls" :key="index" class="wish-link-input"><input v-model="form.urls[index]" class="field" :placeholder="'链接 '+(index+1)+' · https://'" maxlength="1000"/><button role="button" class="text-btn" :aria-label="'移除链接 '+(index+1)" :disabled="submitting" @click="form.urls.splice(index,1)">移除</button></view><text class="small field-help">可填写多条商品或资料地址，仅支持 http / https。空行不会提交。</text></view><button role="button" class="btn" :disabled="!isGuest&&(!canWrite||submitting)" :aria-disabled="!isGuest&&(!canWrite||submitting)" @click="submit">{{submitting?'正在提交…':'提交到心愿清单'}}</button><text v-if="!ready" class="small wish-draft-hint">服务开放前不能提交，填写内容仅保留在当前页面。</text></view>
</view>
</template>
<script setup>
import {inject,ref,reactive,computed,onMounted,onUnmounted} from 'vue';import {api as defaultApi} from '../services/api.js';
const api=inject('portalClient',defaultApi);import {WISH_CATEGORIES,createWishlist,reconcileWishPage,wishStageLabel} from '../services/wishlist.mjs';import ChoiceField from './ChoiceField.vue';import ServerPager from './ServerPager.vue';
const props=defineProps({user:Object,verified:Boolean,guest:Boolean});const emit=defineEmits(['pending','inventory','borrow']);const service=createWishlist(api);
const portalGuest=inject('portalGuest',()=>false),isGuest=computed(()=>props.guest||props.user?.guest||portalGuest());
function guestAction(){if(!isGuest.value)return false;uni.showToast({title:'当前为游客模式，请登录后操作',icon:'none'});return true;}
function openCreate(){if(guestAction())return;tab.value='create';}
const tab=ref('all'),category=ref(''),keyword=ref(''),loading=ref(false),ready=ref(false),unavailable=ref(false),error=ref(''),notice=ref(''),submitting=ref(false),voting=ref('');
const status=ref(props.user?.role==='admin'?'pending':''),stage=ref(''),reasons=reactive({});const statusNames={pending:'待管理员审批',approved:'已批准采购',rejected:'未通过'};
const data=reactive({items:[],total:0,page:1}),form=reactive(emptyForm());
const noticeFading=ref(false);let noticeTimer,noticeClearTimer;
function clearNotice(){clearTimeout(noticeTimer);clearTimeout(noticeClearTimer);notice.value='';noticeFading.value=false;}
function showNotice(text){clearNotice();notice.value=text;noticeTimer=setTimeout(()=>{noticeFading.value=true;noticeClearTimer=setTimeout(()=>{notice.value='';},450);},5000);}
const stageFilters=computed(()=>props.user.role==='admin'?[{value:'',label:'全部状态'},{value:'pending',label:'待管理员审批'},{value:'approved',label:'已批准采购'},{value:'rejected',label:'未通过'}]:[{value:'',label:'全部'},{value:'planned',label:'已列入计划'},{value:'stocked',label:'已采购并上架'}]);
function chooseStage(value){if(props.user.role==='admin')status.value=value;else stage.value=value;load(1);}
const stockingId=ref(''),stockedEquipmentId=ref(''),stockConfirmed=ref(false),stockOptions=ref([]);

function emptyForm(){return {name:'',model:'',category:'单片机',function:'',description:'',urls:['']};}
const wishExample=Object.freeze({name:'FPGA图像处理开发套件',model:'',category:'FPGA',function:'图像采集、处理及显示，希望配套摄像头和显示屏。',description:'用于课程设计中的图像处理实验，完成采集、处理到显示的完整流程。',urls:[]});
function references(row){return Array.isArray(row.urls)?row.urls:(row.url?[row.url]:[]);}
function openReference(url){if(!/^https?:\/\/[^\s]+$/i.test(url))return;
 // #ifdef H5
 window.open(url,'_blank','noopener,noreferrer');return;
 // #endif
 // #ifndef H5
 uni.setClipboardData({data:url});
 // #endif
}
function useExample(){if(guestAction())return;if(submitting.value)return;Object.assign(form,{...wishExample,urls:['']});tab.value='create';error.value='';showNotice(ready.value?'已填入示例，请修改为自己的需求后提交。':'已填入示例，可自行修改；服务开放后才能提交。');uni.pageScrollTo({scrollTop:0,duration:0});}
const interactionReady=computed(()=>ready.value&&props.verified&&!loading.value&&!submitting.value);const canWrite=computed(()=>interactionReady.value&&!voting.value&&!api.pending());let loadRequest=0,activeQuery=null,timer,disposed=false;const syncing=ref(false),syncError=ref('');
async function load(page=1){const request=++loadRequest;loading.value=true;error.value='';clearNotice();try{const result=await service.list({page,category:category.value,keyword:keyword.value,status:status.value,stage:stage.value});if(request!==loadRequest)return;reconcileWishPage(data,result);activeQuery={page:result.page,category:category.value,keyword:keyword.value,status:status.value,stage:stage.value};syncError.value='';ready.value=true;unavailable.value=false;}catch(e){if(request!==loadRequest)return;ready.value=false;if([404,405,501].includes(e.status)){unavailable.value=true;data.items=[];data.total=0;}else{unavailable.value=false;error.value=e.message||'心愿清单暂时无法加载，请重试';}}finally{if(request===loadRequest)loading.value=false;}}
async function submit(){if(guestAction())return;if(!canWrite.value)return;submitting.value=true;error.value='';try{await service.create(form);Object.assign(form,emptyForm());tab.value='all';category.value='';keyword.value='';status.value='';stage.value='';await load(1);showNotice('心愿已提交，等待管理员审批，大家可以查看并支持。');}catch(e){error.value=e.message||'提交失败，请保留填写内容后重试';emit('pending',api.pending());}finally{submitting.value=false;}}
async function support(row){if(guestAction())return;if(!interactionReady.value)return;if(voting.value||api.pending()){showNotice('上一笔操作正在确认，请稍后再点击。');return;}loadRequest++;voting.value=row.id;error.value='';try{const result=await service.support(row);Object.assign(row,result);}catch(e){error.value=e.message||'暂时无法确认支持结果，请刷新';emit('pending',api.pending());}finally{voting.value='';}}
async function review(row,action){if(guestAction())return;if(!canWrite.value)return;const reason=(reasons[row.id]||'').trim();if(action==='reject'&&!reason){error.value='请先填写不通过的原因';return;}const confirmed=await new Promise(resolve=>uni.showModal({title:action==='approve'?'批准采购':'不通过此心愿',content:action==='approve'?'批准后仍需管理员采购到货，再到器材维护手动入库；此次不会增加库存。':reason,success:r=>resolve(r.confirm),fail:()=>resolve(false)}));if(!confirmed)return;voting.value=row.id;error.value='';try{await service.review(row,action,reason);await load(data.page);showNotice(action==='approve'?'已批准采购，库存未改变。':'已记录审批结果。');}catch(e){error.value=e.message||'审批未完成，请刷新后核对';emit('pending',api.pending());}finally{voting.value='';}}
async function beginStocked(row){if(guestAction())return;if(!canWrite.value)return;error.value='';try{const items=[];let page=1,total=0;do{const {data:result}=await api.request('/equipment?pageSize=100&page='+page);items.push(...result.items);total=result.total;page++;}while(items.length<total&&page<=100);stockOptions.value=items.filter(item=>item.active&&item.stock>0).map(item=>({value:item.id,label:item.name+' · '+item.model+'（受管库存 '+item.stock+'）'}));stockingId.value=row.id;stockedEquipmentId.value='';stockConfirmed.value=false;}catch(e){error.value=e.message||'器材列表读取失败，请重试';}}
async function markStocked(row){if(guestAction())return;if(!canWrite.value||!stockConfirmed.value||!stockedEquipmentId.value)return;voting.value=row.id;loadRequest++;error.value='';try{const result=await service.markStocked(row,stockedEquipmentId.value);Object.assign(row,result);stockingId.value='';showNotice('已记录采购上架，器材库存未重复增加。');}catch(e){error.value=e.message||'采购状态尚未确认，请刷新核对';emit('pending',api.pending());}finally{voting.value='';}}
async function refreshCounts(){if(disposed||!ready.value||tab.value!=='all'||!activeQuery||loading.value||syncing.value||submitting.value||voting.value||api.pending())return;
 // #ifdef H5
 if(document.visibilityState!=='visible')return;
 // #endif
 const request=loadRequest,query={...activeQuery};syncing.value=true;try{const result=await service.list(query);if(!disposed&&request===loadRequest&&!voting.value&&!submitting.value){reconcileWishPage(data,result);syncError.value='';}}catch{if(!disposed&&request===loadRequest)syncError.value='自动更新暂时失败，可点击刷新人数重试。';}finally{syncing.value=false;}}
onMounted(()=>{load(1);timer=setInterval(refreshCounts,15000);});onUnmounted(()=>{disposed=true;clearInterval(timer);clearNotice();});
</script>
<style scoped>
@import "../pages/index/live.css";
@import "../pages/index/restore-v1.css";

.wish-example{margin-top:28px;padding-top:24px;border-top:1px dashed #c6d5e3}.wish-example .section-top{margin-bottom:18px}.wish-example .muted{margin-top:9px}.wish-example .wish-art{position:relative}.wish-example-badge{position:absolute;top:12px;right:12px;background:#fff;border:1px solid #cad9e6;border-radius:5px;padding:3px 9px;font-size:12px!important;font-weight:500!important}.wish-example-fill{margin-top:18px}.wish-form-example{display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:10px;background:#eef3f8;border-radius:8px;padding:14px 16px;margin:18px 0}.wish-form-example .small{line-height:1.8}
.wish-review{margin-top:16px}.wish-review .textarea{height:76px;min-height:76px;margin-bottom:12px}.wish-sync{display:block;margin:0 0 14px;line-height:1.8}.wish-tabs{margin-bottom:22px}.wish-filter{margin-bottom:24px}.wish-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:22px}.wish-card{border:1px solid #d7e1eb;border-radius:14px;background:#fff;overflow:hidden;min-width:0}.wish-art{height:160px;display:flex;align-items:center;justify-content:center;gap:18px;background:#eaf0f6;color:#31516b}.wish-art image{width:48px;height:48px;opacity:.65}.wish-art>image:only-child{width:100%;height:100%;opacity:1}.wish-art text{font-weight:650;font-size:20px}.wish-body{padding:22px}.wish-description{display:block;line-height:1.9;margin:16px 0;white-space:pre-wrap;overflow-wrap:anywhere}.wish-card-footer{border-top:1px solid #e2e8ef;padding-top:16px;display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:12px;color:#31516b;font-size:14px}.wish-card-footer .btn{font-size:13px;padding:9px 12px}.wish-unavailable{border:1px solid #cbd9e6;background:#eef3f8;border-radius:12px;padding:20px 22px;display:flex;flex-direction:column;gap:12px;margin-bottom:24px;color:#203e57;line-height:1.8}.wish-unavailable .block-title{color:#31516b}.wish-unavailable .text-btn{align-self:flex-start}.wish-form{max-width:850px}.wish-form>.muted{margin:12px 0}.wish-draft-hint{display:block;margin-top:16px}@media(max-width:1200px){.wish-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}@media(max-width:760px){.wish-grid{grid-template-columns:1fr}.wish-art{height:140px}.wish-tabs .chip{flex:1}.wish-form .time-fields{grid-template-columns:1fr}.wish-unavailable{padding:18px}}
@media(max-width:760px){.wish-tabs,.wish-filter{margin-bottom:16px}.wish-grid{gap:14px}.wish-art{height:112px}.wish-body{padding:14px}.wish-description{margin:12px 0;line-height:1.75}.wish-card-footer{padding-top:12px;gap:8px}.wish-unavailable{padding:14px;gap:9px;margin-bottom:16px;border-radius:10px;font-size:13px}.wish-example{margin-top:20px;padding-top:18px}.wish-example-fill{margin-top:12px}.wish-form-example{padding:12px;margin:14px 0}.wish-form .time-fields{gap:0}}

